package com.whaa.shop.promotion.infrastructure;import com.baomidou.mybatisplus.core.mapper.BaseMapper;import com.whaa.shop.promotion.domain.FlashSale;import org.apache.ibatis.annotations.*;public interface FlashSaleMapper extends BaseMapper<FlashSale>{@Update("UPDATE flash_sale SET stock=stock-#{quantity} WHERE id=#{id} AND enabled=TRUE AND stock>=#{quantity} AND start_at<=NOW() AND end_at>NOW()")int deduct(@Param("id")Long id,@Param("quantity")int quantity);}
